#include "Zancle/HasBuiltin.hpp"


#if ZA_HAS_BUILTIN(__is_constructible) && ZA_HAS_BUILTIN(__add_rvalue_reference)

    ////////////////////////////////////////////////////////////
    #define ZA_IS_MOVE_CONSTRUCTIBLE(...) __is_constructible(__VA_ARGS__, __add_rvalue_reference(__VA_ARGS__))

#else

////////////////////////////////////////////////////////////
// Headers
////////////////////////////////////////////////////////////
    #include <type_traits>


    ////////////////////////////////////////////////////////////
    #define ZA_IS_MOVE_CONSTRUCTIBLE(...) ::std::is_move_constructible_v<__VA_ARGS__>

#endif


namespace za
{
////////////////////////////////////////////////////////////
template <typename T>
inline constexpr bool isMoveConstructible = ZA_IS_MOVE_CONSTRUCTIBLE(T);

} // namespace za
